def main():
    db = SessionLocal()
    try:
        subject = db.scalar(select(Subject).where(Subject.slug == SUBJECT_SLUG))
        if subject is None:
            subject = Subject(slug=SUBJECT_SLUG, name=SUBJECT_NAME)
            db.add(subject)
            db.flush()
            print('[CREATE] Tao subject Vật lý, ID =', subject.id)
        else:
            print('[OK] Tim thay subject Vật lý, ID =', subject.id)

        created = 0
        updated = 0

        for item in LESSONS:
            lesson = db.scalar(select(Lesson).where(
                Lesson.subject_id == subject.id,
                Lesson.grade == item['grade'],
                Lesson.topic == item['topic'],
            ))

            if lesson is None:
                lesson = Lesson(
                    subject_id=subject.id,
                    grade=item['grade'],
                    topic=item['topic'],
                    title=item['title'],
                )
                db.add(lesson)
                created += 1
                status = 'CREATE'
            else:
                updated += 1
                status = 'UPDATE'

            lesson.title = item['title']
            lesson.icon = item['icon']
            lesson.description = item['description']
            lesson.definition = item['definition']
            lesson.concept = item['concept']
            lesson.formulas = item['formulas']
            lesson.meaning = item['meaning']
            lesson.real_life = item['real_life']
            lesson.game_title = item['game_title']
            lesson.game_description = item['game_description']
            lesson.game_type = item['game_type']

            print(f"[{status}] Lop {item['grade']} | {item['topic']} | {item['title']}")

        db.commit()
        print('\n' + '=' * 60)
        print(f'DA XU LY: {len(LESSONS)} BAI VAT LY')
        print(f'TAO MOI: {created}')
        print(f'CAP NHAT: {updated}')
        print('=' * 60)
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == '__main__':
    main()
